const upsertGoogleAccount = `-- name: UpsertGoogleAccount :one

INSERT INTO google_accounts (email, refresh_token, access_token, access_token_expires_at, scopes, status)
VALUES ($1, $2, $3, $4, $5, 'connected')
ON CONFLICT (email) DO UPDATE
SET refresh_token = EXCLUDED.refresh_token,
    access_token = EXCLUDED.access_token,
    access_token_expires_at = EXCLUDED.access_token_expires_at,
    scopes = EXCLUDED.scopes,
    status = 'connected',
    last_sync_error = NULL
RETURNING id, email, label, color, refresh_token, access_token, access_token_expires_at, scopes, status, last_sync_at, last_sync_error, created_at, updated_at
`

type UpsertGoogleAccountParams struct {
	Email                string             `db:"email" json:"email"`
	RefreshToken         []byte             `db:"refresh_token" json:"refresh_token"`
	AccessToken          []byte             `db:"access_token" json:"access_token"`
	AccessTokenExpiresAt pgtype.Timestamptz `db:"access_token_expires_at" json:"access_token_expires_at"`
	Scopes               string             `db:"scopes" json:"scopes"`
}

// ---------------------------------------------------------------------------
// Accounts
// ---------------------------------------------------------------------------
// Re-connecting an already connected account replaces its tokens instead of failing: the
// user re-runs the consent flow precisely when the old grant stopped working.
func (q *Queries) UpsertGoogleAccount(ctx context.Context, arg UpsertGoogleAccountParams) (GoogleAccount, error) {
	row := q.db.QueryRow(ctx, upsertGoogleAccount,
		arg.Email,
		arg.RefreshToken,
		arg.AccessToken,
		arg.AccessTokenExpiresAt,
		arg.Scopes,
	)
	var i GoogleAccount
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.Label,
		&i.Color,
		&i.RefreshToken,
		&i.AccessToken,
		&i.AccessTokenExpiresAt,
		&i.Scopes,
		&i.Status,
		&i.LastSyncAt,
		&i.LastSyncError,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
